from lib import *
r=[]
r.append(R(6671924,"चीज़ी टमाटर और सफ़ेद बीन्स \"पिज़्ज़ा\" स्किलेट",
"यह \"पिज़्ज़ा\" स्किलेट चीज़ी टमाटर बेक के आरामदायक स्वाद को सफ़ेद बीन्स और पालक की पौष्टिकता के साथ जोड़कर एक संतोषजनक एक-पैन भोजन बनाती है। यह पौधों पर आधारित प्रोटीन और फाइबर से भरपूर है, जो रक्त शर्करा (ब्लड ग्लूकोज़) के स्तर को स्थिर रखने में मदद कर सकते हैं।",
"4","2 कप",
["1 छोटा चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","1/2 छोटा प्याज़ (बारीक कटा हुआ)","2 फांक लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच सूखा ओरेगैनो","1/2 छोटा चम्मच कुटी हुई लाल मिर्च के फ्लेक्स (वैकल्पिक)","1 1/2 कप डिब्बाबंद कुचले हुए टमाटर (बिना अतिरिक्त नमक के)","1 कप कम सोडियम वाला सब्ज़ियों का ब्रॉथ","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 (15 औंस) डिब्बा कैनेलिनी बीन्स (बिना अतिरिक्त नमक के, निथारे और धोए हुए)","4 कप बेबी पालक (कटा हुआ)","2 औंस आंशिक रूप से वसा निकाली हुई मोत्ज़ारेला (कद्दूकस की हुई)","1 बड़ा चम्मच पार्मेसन चीज़ (कद्दूकस किया हुआ)","2 बड़े चम्मच ताज़ी तुलसी (कटी हुई)"],
["ओवन को ब्रॉयल पर पहले से गरम करें।","एक बड़े ओवन-सुरक्षित स्किलेट में मध्यम आँच पर ज़ैतून का तेल गरम करें। प्याज़ डालें और नरम होने तक पकाएँ, लगभग 3-4 मिनट। लहसुन, ओरेगैनो और लाल मिर्च के फ्लेक्स डालकर चलाएँ और खुशबू आने तक 30 सेकंड पकाएँ।","कुचले हुए टमाटर और सब्ज़ियों का ब्रॉथ डालें, फिर नमक और काली मिर्च से स्वाद बनाएँ। बीच-बीच में चलाते हुए 5 मिनट उबलने दें।","सफ़ेद बीन्स और पालक डालकर चलाएँ और 3-4 मिनट और पकाएँ, जब तक पालक मुरझा न जाए और बीन्स अंदर तक गरम न हो जाएँ।","मोत्ज़ारेला और पार्मेसन को स्किलेट पर समान रूप से छिड़कें। स्किलेट को ओवन में रखें और चीज़ के पिघलने और सुनहरा भूरा होने तक ब्रॉयल करें, 2-3 मिनट।","ओवन से निकालें और ताज़ी तुलसी से सजाएँ।"]))
r.append(R(6672724,"बालसैमिक विनिग्रेट के साथ सरल साइड सलाद",
"सब्ज़ियों की सही मात्रा वाला और ऊपर से डालने के लिए सलाद ड्रेसिंग के साथ एक भरोसेमंद साइड सलाद हमेशा अच्छा रहता है। जब आप जल्दी में हों, तो यह भोजन की तैयारी में अंदाज़ा लगाने की झंझट ख़त्म कर देता है, ताकि आप आराम से बैठकर अपने भोजन का आनंद ले सकें।",
"4","1 ½ कप",
["3 कप मिली-जुली हरी पत्तेदार सब्ज़ियाँ","1 मध्यम खीरा (पतला कटा हुआ)","1 कप चेरी टमाटर (आधे कटे हुए)","1/4 कप लाइट बालसैमिक विनिग्रेट"],
["मिली-जुली हरी पत्तेदार सब्ज़ियाँ, खीरा और टमाटर एक बड़े कटोरे में डालें। मिलाएँ।","लाइट बालसैमिक विनिग्रेट डालें और सब्ज़ियों पर समान रूप से लगाने के लिए फिर से मिलाएँ।"]))
r.append(R(6672801,"क्रीमी हॉर्सरैडिश सॉस के साथ रोस्ट बीफ़",
"इस रोस्ट बीफ़ जैसे कम वसा वाले मांस त्योहारों के लिए शानदार मुख्य व्यंजन बन सकते हैं, जो पूरे परिवार को पसंद आएगा।",
"14","3 औंस मांस और 3 बड़े चम्मच सॉस",
["3 पाउंड बीफ़ रोस्ट, बॉटम राउंड, कम वसा वाला, ⅛” ट्रिम, बिना हड्डी का (सारी अतिरिक्त चर्बी हटाई हुई; भूनने से पहले 15 मिनट कमरे के तापमान पर रखें)","1 1/2 बड़े चम्मच काली मिर्च","2 छोटे चम्मच कोशर नमक","5 फांक लहसुन (बहुत बारीक कटा हुआ)","1/2 कप हॉर्सरैडिश (छिली, ताज़ा कद्दूकस की हुई, या तैयार हॉर्सरैडिश)","2 कप बिना वसा वाली सावर क्रीम","1/4 कप दरदरी डिजॉन सरसों"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। काली मिर्च, नमक और लहसुन मिलाएँ और पूरे रोस्ट पर मलें। मांस को एक बड़े रोस्टिंग पैन में रखें। मांस को लगभग 20 मिनट भूनें।","आँच को 325 डिग्री F तक कम करें और लगभग 50 मिनट और बेक करें, या जब तक रोस्ट में डाला गया मीट थर्मामीटर मीडियम रेयर के लिए 140 डिग्री F न दिखाए। चाहें तो और देर तक पकाएँ।","रोस्ट को ओवन से निकालें। ढीले ढंग से फ़ॉइल से ढकें और 15-20 मिनट रखा रहने दें। मांस को रेशों के आर-पार पतले स्लाइस में काटें।","हॉर्सरैडिश सॉस बनाने के लिए हॉर्सरैडिश, सावर क्रीम और सरसों मिलाएँ। कटे हुए बीफ़ के साथ परोसें।"]))
r.append(R(6673467,"भुनी पत्ता गोभी चिकन पार्मेसन",
"चिकन पार्मेसन में यह चतुराई भरा बदलाव आम पास्ता की जगह भुने पत्ता गोभी के स्टेक रखता है, जिससे अतिरिक्त फाइबर मिलता है और कार्बोहाइड्रेट नियंत्रण में रहते हैं। रसीला कतरा हुआ चिकन और पिघला हुआ चीज़ भारीपन के बिना आरामदायक भोजन का अहसास देते हैं। यह स्वादिष्ट, रक्त शर्करा (ब्लड ग्लूकोज़) के अनुकूल डिनर है जो मधुमेह का ध्यान रखने वाली भोजन योजना में आसानी से फिट बैठता है। यह कम कार्बोहाइड्रेट वाली रेसिपी है।",
"4","चिकन के 1/2 कप के साथ पत्ता गोभी का 1 स्लाइस",
["1 छोटी हरी पत्ता गोभी (4 मोटे स्लाइस में कटी)","1 बड़ा चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच प्याज़ पाउडर","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 कप चिकन ब्रेस्ट (पका हुआ, कतरा हुआ)","1 कप डिब्बाबंद कुचले हुए टमाटर (बिना नमक मिलाए)","1/2 छोटा चम्मच सूखा ओरेगैनो","1/4 छोटा चम्मच कुटी हुई लाल मिर्च के फ्लेक्स (वैकल्पिक)","1/2 कप मोत्ज़ारेला चीज़ (आंशिक रूप से वसा निकाला हुआ, कद्दूकस किया हुआ)","2 बड़े चम्मच पार्मेसन चीज़","2 बड़े चम्मच ताज़ी तुलसी (कटी हुई)"],
["ओवन को 400°F पर पहले से गरम करें और बेकिंग शीट पर बेकिंग पेपर बिछाएँ। पत्ता गोभी के स्लाइस शीट पर सजाएँ और ऊपर से हल्का ज़ैतून का तेल ब्रश से लगाएँ। लहसुन पाउडर, प्याज़ पाउडर, नमक और काली मिर्च छिड़कें। 20 मिनट भूनें, बीच में पलट दें, जब तक किनारे सुनहरे और थोड़े कुरकुरे न हो जाएँ।","जब पत्ता गोभी भुन रही हो, तब एक छोटे सॉसपैन को मध्यम आँच पर गरम करें। कुचले हुए टमाटर, ओरेगैनो और लाल मिर्च के फ्लेक्स (अगर इस्तेमाल कर रहे हों) डालें। बीच-बीच में चलाते हुए 5 मिनट उबलने दें, जब तक थोड़ा गाढ़ा न हो जाए। एक कटोरे में कतरे हुए चिकन को 2 बड़े चम्मच टमाटर की सॉस के साथ मिलाएँ ताकि वह नम रहे।","पत्ता गोभी को ओवन से निकालें और कतरे हुए चिकन को हर स्लाइस पर समान रूप से बाँटें। बची हुई टमाटर की सॉस को चिकन की परत पर चम्मच से डालें। मोत्ज़ारेला और पार्मेसन छिड़कें।","वापस ओवन में रखें और 10 मिनट और बेक करें, या जब तक चीज़ पिघलकर हल्का सुनहरा न हो जाए।"]))
r.append(R(6673785,"साबुत अनाज का हैमबर्गर बन",
"साबुत अनाज के हैमबर्गर बन की पोषण संबंधी जानकारी",
"1","1 पूरा बन",
["1 पूरा साबुत अनाज का हैमबर्गर बन"],[]))
r.append(R(6673913,"तरबूज़-आम की सालसा के साथ चिपोटले सैल्मन",
"यह बेक किया हुआ व्यंजन सप्ताह के किसी भी दिन के आसान भोजन के लिए जल्दी बन जाता है, जो पोषक तत्वों और स्वाद से भरपूर है। मधुमेह वाले लोगों के लिए एकदम सही, चिपोटले सैल्मन के हल्के तीखेपन को तरबूज़ और आम से बनी ताज़ा फलों की सालसा के चटक, मीठे स्वाद से संतुलित किया जाता है। गर्मियों की रात के बेहतरीन भोजन के लिए इस रेसिपी को धनिया-नींबू क्विनोआ के साथ जोड़कर देखें!",
"4","1 सैल्मन फिले + ½ कप सालसा",
["4 (4 औंस) सॉकआई सैल्मन के फिले","1/2 कप एडोबो सॉस में चिपोटले मिर्च (कटी हुई)","1 बड़ा चम्मच ज़ैतून का तेल","2 कप बिना बीज का तरबूज़ (छोटे टुकड़ों में कटा)","15 औंस पानी में पैक किया डिब्बाबंद आम (निथारा और छोटे टुकड़ों में कटा)","1/2 छोटा लाल प्याज़ (छोटे टुकड़ों में कटा)","1 पूरी हरी मिर्च (जैलापेन्यो) (बारीक कटी हुई)","1 छोटा चम्मच नींबू का ज़ेस्ट (लाइम)","2 बड़े चम्मच ताज़ा नींबू का रस (लाइम)","1/4 छोटा चम्मच कोशर नमक","1/8 छोटा चम्मच काली मिर्च","1/4 कप ताज़ा हरा धनिया (कटा हुआ)"],
["ओवन को 400°F पर पहले से गरम करें। बेकिंग शीट पर एल्युमिनियम फ़ॉइल बिछाएँ। सैल्मन के फिले बेकिंग शीट पर रखें।","एडोबो सॉस वाली मिर्चों को बारीक काटें और ज़ैतून के तेल के साथ एक छोटे कटोरे में रखें, चलाकर मिलाएँ। मिश्रण को हर सैल्मन फिले पर फैलाएँ।","बेकिंग शीट को ओवन में रखें और 8-10 मिनट बेक करें, जब तक सैल्मन 145°F न दिखाए।","इस बीच, एक कटोरे में तरबूज़, आम, लाल प्याज़, जैलापेन्यो, नींबू का ज़ेस्ट और रस, नमक, काली मिर्च और हरा धनिया मिलाएँ। सालसा तैयार करने के लिए चलाकर मिलाएँ।","मछली को प्लेटों में बाँटें और ऊपर तरबूज़ की सालसा डालें।"]))
r.append(R(6673934,"भुने हुए दालचीनी वाले सेब",
"जल्दी बनने वाले, पौष्टिक और एप्पल पाई जैसी खुशबू वाले, इसमें क्या पसंद न आए? अपनी अगली झटपट मिठाई के लिए दालचीनी, वनीला और शहद से चमकाए हुए कटे फल बनाएँ। और ज़्यादा स्वाद के लिए, ऊपर से भुने हुए कटे अखरोट डालें।",
"4","1/2 कप",
["1 बड़ा चम्मच मार्जरीन (ट्रांस-फैट रहित)","2 बड़े ग्रैनी स्मिथ सेब (छिले और कटे हुए)","1/2 छोटा चम्मच पिसी दालचीनी","1 छोटा चम्मच वनीला एक्सट्रैक्ट","3 बड़े चम्मच पानी","1 बड़ा चम्मच शहद या 2 पैकेट कृत्रिम स्वीटनर"],
["एक सॉते पैन में मध्यम-तेज़ आँच पर मार्जरीन गरम करें। सेब डालें और बार-बार चलाते हुए 3 मिनट भूनें।","बाकी सामग्री डालें। आँच धीमी करें और बीच-बीच में चलाते हुए 12 मिनट उबलने दें।"]))
r.append(R(6674090,"स्टू किए टमाटर के साथ मोरक्कन दाल",
"आप दाल को पहले से तैयार कर सकते हैं, ताकि सप्ताह के किसी भी दिन कुछ ही मिनटों में तैयार होने वाला झटपट भोजन बन जाए। इसे मिक्स्ड पेपर मेडली के साथ जोड़कर एक संतोषजनक वीगन व्यंजन बनाएँ, जो पौधों पर आधारित प्रोटीन और बिना स्टार्च वाली सब्ज़ियों से भरपूर है।",
"8","1/2 कप",
["1 कप बिना पकी भूरी दाल (साबुत मसूर) (छँटी और धोई हुई)","1 कप डिब्बाबंद कटे हुए टमाटर (बिना नमक मिलाए)","1 मध्यम पीला प्याज़ (कटा हुआ)","1 छोटा चम्मच पिसा धनिया","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/4 कप ताज़ा हरा धनिया (कटा हुआ)"],
["दाल को एक मध्यम सॉसपैन में रखें और ढकने लायक पानी डालें। तेज़ आँच पर उबाल आने दें, आँच धीमी करें और ढककर 30 मिनट उबलने दें, या जब तक नरम न हो जाए। निथारकर अलग रख दें। (यह चरण एक दिन पहले भी किया जा सकता है।)","दाल, टमाटर, प्याज़, धनिया, नमक और काली मिर्च को एक बड़े सॉसपैन में मिलाएँ। 1 कप पानी डालें और तेज़ आँच पर उबाल आने दें। आँच धीमी करें और ढककर 10 मिनट उबलने दें।","हरा धनिया डालें और चलाएँ। गरमागरम परोसें।"]))
r.append(R(6674242,"फ़ाइलो के साथ चिकन पॉट पाई",
"परतदार क्रस्ट से ढके गाढ़े, रसीले सॉस में चिकन और सब्ज़ियों से ज़्यादा आरामदायक कुछ नहीं है। इस व्यंजन की मिट्टी जैसी सोंधी खुशबू आपकी रसोई को भर देगी और सबको खाने के लिए बुला लेगी। इस सर्वोत्तम आरामदायक भोजन का राज़? मक्खन के स्वाद वाले स्प्रे और फ़ाइलो आटे का उपयोग करके हम सामान्य पाई क्रस्ट टॉपिंग में पाई जाने वाली सारी संतृप्त वसा और कैलोरी में भारी कटौती करते हैं। फ़ाइलो आटे की टॉपिंग सामान्य क्रस्ट से कहीं ज़्यादा दिलचस्प है।",
"12","1 (3 × 3 इंच) चौकोर टुकड़ा",
["1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (1/2 इंच के टुकड़ों में कटे)","1 1/2 छोटा चम्मच लहसुन पाउडर","1 चुटकी काली मिर्च","2 कप कम सोडियम वाला चिकन ब्रॉथ (वसा रहित)","1/2 कप पानी","1 छोटा चम्मच ज़ैतून का तेल","10 औंस क्रेमिनी (बेबी बेला) मशरूम (1/2 इंच के टुकड़ों में कटे (लगभग 3 कप))","1 फांक लहसुन (बारीक कटा हुआ)","1/8 छोटा चम्मच कोशर नमक","1 पाउंड लाल आलू (बिना छिले और चार टुकड़ों में कटे)","5 टहनी ताज़ा थाइम","3 मध्यम गाजर (1/2 इंच के टुकड़ों में कटी)","1 बड़ा प्याज़ (कटा हुआ)","1 1/2 कप 1% वसा वाला दूध","1/2 कप हाफ-एंड-हाफ","6 बड़े चम्मच मैदा (ऑल-पर्पज़ आटा)","8 औंस जमे हुए मटर","1/2 कप पार्सले (फ़्लैट लीफ़, बारीक कटा हुआ)","8 पूरी शीट जमा हुआ फ़ाइलो आटा","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["ओवन को 400°F पर पहले से गरम करें। कटे हुए चिकन पर लहसुन पाउडर और ताज़ी पिसी काली मिर्च छिड़कें और अलग रख दें। एक 2-क्वार्ट सॉसपैन में चिकन स्टॉक और पानी को उबालें।","इस बीच, एक मध्यम स्किलेट में ज़ैतून का तेल गरम करें और मशरूम और लहसुन डालें। हल्का नमक और काली मिर्च छिड़कें। 5 मिनट पकाएँ या जब तक मशरूम नरम न हो जाएँ। मशरूम के नरम हो जाने पर, उन्हें एक कटोरे में अलग रख दें। मशरूम से निकला कोई भी तरल छान दें।","आलू और थाइम की पत्तियाँ डालें और आँच को मध्यम कर दें। आलू को लगभग 8 मिनट उबलने दें जब तक नरम न हो जाएँ। छेद वाले चम्मच से आलू और थाइम को एक कटोरे में निकाल लें। थाइम की पत्तियाँ फेंक दें। स्टॉक में गाजर और प्याज़ डालें और 4 मिनट उबलने दें। छेद वाले चम्मच से गाजर और प्याज़ को आलू वाले उसी कटोरे में निकाल लें।","चिकन को स्टॉक में डालें और चिकन को 3 मिनट उबलने दें। छेद वाले चम्मच से चिकन को सब्ज़ियों वाले उसी कटोरे में निकाल लें। स्टॉक को तब तक कम करें जब तक वह 1/2 कप न रह जाए, लगभग 10 मिनट।","इस बीच, एक कटोरे में दूध, हाफ-एंड-हाफ और मैदा को तब तक फेंटें जब तक वह बिल्कुल चिकना न हो जाए। जब स्टॉक कम हो जाए, तो दूध का मिश्रण धीरे-धीरे स्टॉक में डालें, लगातार चलाते हुए जब तक वह गाढ़ा लेकिन चिकना न हो जाए। सॉस को सब्ज़ियों में डालें और नमक व काली मिर्च से स्वाद बनाएँ। अलग रखे मशरूम, मटर और पार्सले डालें और अच्छी तरह मिलाएँ।","मिश्रण को 9 × 13 इंच के पैन में डालें। एक तरफ़ रख दें।","फ़ाइलो की एक शीट को बहुत हल्के आटे लगी सतह पर फैलाएँ। ध्यान रखें कि बाकी फ़ाइलो शीट्स को तौलिये से ढककर रखें ताकि वे हवा के संपर्क में न आएँ। खुला रहने पर फ़ाइलो चटक जाएगा। उस पर बटर स्प्रे लगाएँ। पहली शीट के ऊपर फ़ाइलो की एक और शीट रखें और उस पर स्प्रे करें। यह प्रक्रिया तब तक दोहराएँ जब तक सभी 8 शीट्स का उपयोग न हो जाए।","फ़ाइलो आटे की परतों को सावधानी से उठाकर चिकन-सब्ज़ी की फ़िलिंग के ऊपर रखें। किनारों को अंदर की ओर मोड़ दें। तेज़ चाकू से आटे के ऊपर 3 तिरछे चीरे लगाएँ। इससे भाप बाहर निकल सकेगी।","चिकन पॉट पाई को बिना ढके लगभग 30 मिनट बेक करें, जब तक ऊपरी हिस्सा फूलकर सुनहरा भूरा न हो जाए। ओवन से निकालें और लगभग 5 मिनट रखा रहने दें। चौकोर टुकड़ों में काटें।"]))
r.append(R(6674650,"सेब और पीनट बटर",
"पीनट बटर को अक्सर ऐसा भोजन माना जाता है जिससे डायलिसिस पर रहने वाले लोगों को बचना चाहिए। हालाँकि, यह प्रोटीन का बढ़िया स्रोत हो सकता है। फल और नट बटर प्रोटीन और कार्बोहाइड्रेट के संतुलन के कारण मधुमेह वाले लोगों के लिए भी एक लोकप्रिय नाश्ता है। मात्रा हमेशा महत्वपूर्ण होती है, इसलिए इस सेब और पीनट बटर के नाश्ते में बताई गई सर्विंग की सिफ़ारिश का पालन ज़रूर करें।",
"2","1/2 सेब + 1 बड़ा चम्मच पीनट बटर",
["2 बड़े चम्मच पीनट बटर","1 छोटा सेब (लगभग बेसबॉल के आकार का)"],
["सेब को 8 फांकों में काटें और कोर निकाल दें।","हर सेब की फांक पर लगभग 3/4 छोटा चम्मच पीनट बटर लगाएँ।"]))
